              <div><label className={df.label}>Hồ sơ</label><Input disabled={readOnly} maxLength={30} data-testid="ct-pnb-field-maHsH" value={form.maHsH} onChange={event => touch({ ...form, maHsH: event.target.value, tenHsH: '' })} /></div>
