function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listPnbReceipts(
  query: Record<string, string | number | boolean>,
): Promise<PnbReceiptListItem[]> {
  const res = await apiClient.get<BffResponse<PnbReceiptListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getPnbReceipt(sttRec: string): Promise<PnbReceipt> {
  const res = await apiClient.get<BffResponse<PnbReceipt>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createPnbReceipt(body: PnbReceiptWrite): Promise<PnbReceipt> {
  const res = await apiClient.post<BffResponse<PnbReceipt>>(BASE, body);
  return unwrap(res);
}

export async function updatePnbReceipt(sttRec: string, body: PnbReceiptWrite): Promise<PnbReceipt> {
  const res = await apiClient.put<BffResponse<PnbReceipt>>(`${BASE}/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}
